import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.BEUshCVJ.js";const p=JSON.parse('{"title":"Briefing material","description":"","frontmatter":{},"headers":[],"relativePath":"guide/materials.md","filePath":"guide/materials.md","lastUpdated":1792715383000}'),i={name:"guide/materials.md"};function s(n,e,l,d,c,h){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="briefing-material" tabindex="-1">Briefing material <a class="header-anchor" href="#briefing-material" aria-label="Permalink to &quot;Briefing material&quot;">​</a></h1><p>This page shows how to give MeetCue background about you and the meeting, so the hints match what you would actually say.</p><h2 id="describe-your-role" tabindex="-1">Describe your role <a class="header-anchor" href="#describe-your-role" aria-label="Permalink to &quot;Describe your role&quot;">​</a></h2><p>In <strong>Settings › Hints › My role</strong>, write one sentence about yourself, for example:</p><blockquote><p>Network architect with 8 years in data center operations</p></blockquote><p>The hint model writes talking points from this perspective.</p><h2 id="add-files" tabindex="-1">Add files <a class="header-anchor" href="#add-files" aria-label="Permalink to &quot;Add files&quot;">​</a></h2><ol><li>Open <strong>Settings › Hints</strong>.</li><li>Under <strong>Briefing material</strong>, click <strong>Add a file…</strong>.</li><li>Choose an agenda, résumé, project notes or similar. Supported formats are <code>.txt</code>, <code>.md</code>, <code>.docx</code> and <code>.pdf</code>.</li></ol><p>MeetCue extracts the text on your computer and shows how many characters were found. Scanned PDFs without a text layer yield no text; export them with text recognition first.</p><h2 id="what-is-sent" tabindex="-1">What is sent <a class="header-anchor" href="#what-is-sent" aria-label="Permalink to &quot;What is sent&quot;">​</a></h2><ul><li>A short excerpt of the material is included in the hint model&#39;s instructions, so hints can refer to your projects and the agenda.</li><li>The most distinctive terms (product names, acronyms, people&#39;s names) are sent to the speech recognition provider as hints, so they are recognised correctly.</li><li>The full text stays on your computer. It is never included in diagnostics exports.</li></ul><p>The material is placed in the part of the instructions that stays the same during a meeting. Providers that support prompt caching then charge much less for it after the first question.</p><h2 id="keep-it-focused" tabindex="-1">Keep it focused <a class="header-anchor" href="#keep-it-focused" aria-label="Permalink to &quot;Keep it focused&quot;">​</a></h2><p>Long material makes every hint request larger and slower to start. One or two pages that match the meeting work better than a full document archive. Remove files you no longer need with <strong>Remove</strong>.</p>',14)])])}const m=t(i,[["render",s]]);export{p as __pageData,m as default};
